// IMAGE: a deep blue background with a soft light in the middle. The curves are drawn by the
// [Canvas2D] tab, over this.
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = (2.0 * fragCoord - iResolution.xy) / iResolution.y;
  float glow = exp(-1.5 * dot(uv, uv));
  vec3 color = mix(vec3(0.008, 0.004, 0.08), vec3(0.05, 0.06, 0.2), glow);
  fragColor = vec4(color, 1.0);
}

