// CANVAS2D: two circles roll around a fixed one, one inside and one outside, and a point on each
// traces its curve. A port of an animation drawn with the same nested-list helpers.
// [Sliders] sets n, how many times the small circles fit around the big one.

const DURATION = 12;

// The integral of smoothstep from a to t: speeds up from 0, then goes on at 1 per second.
function smoothstepIntegral(t, a, b) {
  if (t <= a) return 0;
  if (t >= b) return (b - a) / 2 + (t - b);
  const u = (t - a) / (b - a);
  return (b - a) * (u * u * u - u * u * u * u / 2);
}

// Points from `from` towards `to`, `step` apart.
function range(from, to, step) {
  const points = [];
  for (let x = from; step > 0 ? x < to : x > to; x += step) points.push(x);
  return points;
}

function draw(ctx, {time, floats}) {
  clear(ctx);
  // Eases in, turns twice round at a steady speed, then eases out again.
  let theta = 4 * Math.PI *
    (smoothstepIntegral(time, 0, 4) - smoothstepIntegral(time, DURATION - 4, DURATION)) / (DURATION - 4);
  theta = Math.min(theta, 4 * Math.PI - 1e-5);
  const n = Math.max(2, Math.round(floats[0]));
  const r = 1 / n;
  // The first time round draws the curves; the second rubs them out.
  const firstHalf = theta < 2 * Math.PI;
  const inside = th => [
    Math.sin(th) * (1 - r) - Math.sin(th * (1 - r) / r) * r,
    Math.cos(th) * (1 - r) + Math.cos(th * (1 - r) / r) * r,
  ];
  const outside = th => [
    Math.sin(th) * (1 + r) - Math.sin(th * (1 + r) / r) * r,
    Math.cos(th) * (1 + r) - Math.cos(th * (1 + r) / r) * r,
  ];
  const angles = range(firstHalf ? 0 : 4 * Math.PI, theta, firstHalf ? 0.01 : -0.01);
  const plotRange = 1 + 2 * r + 0.1;
  // A point on a rolling circle.
  const dot = Disk({center: [0, 1], radius: 16, edge: true, radiusInPixels: true});

  drawList(ctx, [
    AbsoluteLineWidth(4),
    Set({strokeStyle: "#ffffff"}),
    Disk({center: [0, 0], radius: 1, fill: false, edge: true}),
    [
      Set({strokeStyle: "#bbeafe"}),
      Line({pts: angles.map(inside)}),
      Line({pts: angles.map(outside)}),
    ],
    [
      Rotate({angle: -theta}),  // Clockwise, as the curves go.
      Set({fillStyle: "#ffffff16"}),
      [
        Disk({center: [0, 1 - r], radius: r, edge: true}),
        Rotate({angle: theta / r, center: [0, 1 - r]}),
        Set({fillStyle: "#f39034", strokeStyle: "black"}),
        dot,
      ],
      [
        Disk({center: [0, 1 + r], radius: r, edge: true}),
        Rotate({angle: -theta / r, center: [0, 1 + r]}),
        Set({fillStyle: "#f39034", strokeStyle: "black"}),
        dot,
      ],
    ],
  ], {xmin: -plotRange, xmax: plotRange, ymin: -plotRange, ymax: plotRange});
}
